import { chapter } from "./resource-chapter";

type CUnit = [string,string,string,string,string,string,string,string,string,string,string,string];
function cChapter(section:string, rows:CUnit[]) {
  return chapter(section, rows.map(([id,title,summary,detail,a,b,c,question,answer,wrongA,wrongB,why])=>({
    id,title,summary,content:[detail,"Build examples with compiler warnings enabled and test them using small, known inputs. In C, array bounds, pointer validity, and allocation lifetime are the programmer's responsibility, so check each before using a value."],
    level:"Beginner" as const,
    examples:[a,b,c].map((code,index)=>({title:`Example ${index+1}`,code,result:"Compile and run the example, then compare its output with the expected behavior."})),
    quizzes:[
      {question,options:[answer,wrongA,wrongB],answer:0,explanation:why},
      {question:`Which idea about ${title} is accurate?`,options:[answer,wrongB,wrongA],answer:0,explanation:why},
      {question:`When using ${title}, what should you remember?`,options:[answer,wrongA,wrongB],answer:0,explanation:why},
    ],
  })));
}

export const cLessons = [
  ...cChapter("C Foundations", [
    ["c-intro","What C Is Used For","Understand C as a compiled language with direct control over data and memory.","C is a general-purpose language used in operating systems, embedded devices, libraries, and performance-sensitive programs. It compiles source into a native program, while the programmer explicitly manages many low-level details.","#include <stdio.h>\nint main(void) { puts(\"Hello\"); }","gcc -std=c11 -Wall -Wextra hello.c -o hello","./hello","What is a common strength of C?","Precise control over data representation and resources","Automatic memory safety for every pointer","Built-in web page styling","C offers low-level control but requires careful memory and bounds handling."],
    ["c-get-started","Compiling and Running C","Create a source file, compile it, and run the generated program.","A compiler translates C source into an executable. Use warnings such as -Wall and -Wextra, fix warnings instead of suppressing them, and compile with the standard version your project targets.","gcc -std=c11 -Wall -Wextra main.c -o app","clang -std=c17 -Wall -Wextra main.c -o app","./app","What does a compiler produce from C source?","An executable program","A database table","A browser stylesheet","Compilation translates source code into a program the system can run."],
    ["c-syntax","C Program Structure and Syntax","Write declarations and statements inside a conventional program entry point.","A hosted C program usually starts in main and includes headers for library declarations. Statements end with semicolons; braces group function and control-flow bodies.","#include <stdio.h>\nint main(void) { return 0; }","int add(int a, int b) { return a + b; }","if (ready) { puts(\"go\"); }","What is the usual entry function in a hosted C program?","main","start","printf","main is the conventional program entry point."],
    ["c-output","Printing Output with printf","Format values using conversion specifiers that match their types.","printf writes formatted text to standard output. Use the correct specifier, such as %d for int and %s for a null-terminated string; a mismatch can cause undefined behavior.","printf(\"Count: %d\\n\", count);","printf(\"Name: %s\\n\", name);","printf(\"Mean: %.2f\\n\", mean);","Why must printf format specifiers match the arguments?","A mismatch can cause incorrect behavior","The compiler changes the variable type","It sorts the output","Variadic formatting relies on matching specifiers to actual argument types."],
    ["c-comments","Writing C Comments","Annotate intent without changing program execution.","C supports // line comments and /* block comments */. Comments should explain reasoning or constraints and stay updated when code changes.","// Validate before using the index","/* A block comment\n   may span lines. */","int total = 0; // running total","Do comments execute as statements?","No, the compiler ignores comments","Only block comments execute","Comments run after main","Comments document source code but do not execute."],
    ["c-variables","Declaring and Updating Variables","Give values names and choose a type before using them.","A declaration gives a variable a type and name. Initialize variables before reading them; uninitialized automatic variables do not have a predictable value.","int attempts = 0;","double temperature = 21.5;","attempts += 1;","Why initialize a local variable before reading it?","Its initial value is otherwise indeterminate","C fills it with zero in every case","Initialization allocates a file","Reading an uninitialized automatic object can produce undefined behavior."],
    ["c-data-types","C Scalar and Derived Types","Choose integer, floating, character, and derived types deliberately.","C includes integer types, floating-point types, _Bool, arrays, structs, unions, enums, and pointers. Exact widths of many integer types depend on the implementation; use stdint.h when fixed-width values are required.","int count = 12;","double ratio = 0.75;","char grade = 'A';","Does int have the same exact width on every C implementation?","No, its width is implementation-dependent","Yes, exactly 64 bits","It has no width","The C standard defines minimum ranges, not one universal int size."],
    ["c-type-conversion","Converting Between C Types","Use casts and promotions with awareness of lost range or precision.","C performs integer promotions and conversions in expressions. A cast requests a conversion but does not guarantee the value fits; narrowing may discard information, and signed overflow is undefined.","double mean = (double) total / count;","int whole = (int) 7.9;","unsigned char byte = (unsigned char) value;","What can happen when a value is narrowed?","Range or fractional information may be lost","The program becomes memory-safe","The source file is renamed","A conversion can change the representable value."],
    ["c-constants","Using const and Object-like Constants","Mark values that should not be changed through a particular name.","const qualifies an object as non-modifiable through that lvalue. A #define creates a preprocessing replacement; use clear names and choose the mechanism that fits the value and scope.","const double tax_rate = 0.08;","#define MAX_USERS 100","enum { BUFFER_CAPACITY = 64 };","What does const communicate for an object?","Do not modify it through that name","The value is automatically stored on disk","The variable becomes a pointer","const restricts modification through the qualified lvalue."],
    ["c-operators","C Arithmetic and Comparison Operators","Compute values and compare them with clear types.","C operators include arithmetic, comparison, assignment, and logical operators. Integer division truncates toward zero; use a floating operand when fractional results are intended.","int next = value + 1;","double half = value / 2.0;","bool same = (left == right);","What is the result of integer division 7 / 2?","3","3.5","A compile error in every C version","Both operands are integers, so the fractional part is discarded."],
    ["c-booleans","Boolean Conditions in C","Use truth values and stdbool.h for readable boolean declarations.","In C, scalar expressions can be tested as conditions: zero is false and nonzero is true. In C99 and later, stdbool.h provides bool, true, and false spellings.","#include <stdbool.h>\nbool ready = true;","if (count != 0) { /* work */ }","bool valid = (score >= 50);","How is zero treated in a C condition?","As false","As true","As a null pointer in all contexts","Zero is false in scalar conditions."],
    ["c-if-else","Choosing a Path with if and else","Run code based on a condition.","if evaluates a scalar condition, while else provides a fallback. Use braces consistently, especially when conditions are nested, and parenthesize mixed logical expressions for clarity.","if (score >= 50) { puts(\"pass\"); }","if (ready) { run(); } else { wait(); }","if (x > 0) { sign = 1; } else if (x < 0) { sign = -1; } else { sign = 0; }","When does else execute?","When the associated if condition is false","Before if is checked","At the end of every loop","else handles the alternate branch."],
    ["c-switch","Selecting a Case with switch","Choose among integer or enumeration case labels.","switch evaluates an integer-compatible expression and jumps to a matching case. Add break to avoid falling through unless fall-through is intentional and documented; include default when useful.","switch (choice) { case 1: puts(\"one\"); break; default: puts(\"other\"); }","switch (status) { case 200: label = \"ok\"; break; case 404: label = \"missing\"; break; }","switch (direction) { case NORTH: move_up(); break; case SOUTH: move_down(); break; default: handle_invalid(); }","What does break usually prevent in a switch?","Execution continuing into the next case","A variable being initialized","The program from compiling","break exits the switch statement."],
    ["c-while-loop","Repeating with while","Repeat a block while a condition remains true.","A while loop checks its condition before every iteration, so its body may run zero times. Ensure the loop updates state so it can eventually stop.","while (remaining > 0) { --remaining; }","while (*p != '\\0') { ++p; }","while (!done) { done = step(); }","Can a while loop run zero times?","Yes, if its first condition is false","No, every loop runs once","Only if it contains break","while tests its condition before entering the body."],
    ["c-for-loop","Repeating with for","Use initialization, condition, and update expressions for counted loops.","A for loop groups its setup, continuation test, and update. Use a size_t index for array lengths and ensure the condition never accesses an index outside the valid range.","for (int i = 0; i < 5; ++i) { printf(\"%d\\n\", i); }","for (size_t i = 0; i < length; ++i) { use(items[i]); }","for (int n = 10; n > 0; --n) { total += n; }","Which part runs after each for-loop body iteration?","The update expression","The initialization expression","The function declaration","The update expression advances the loop state."],
    ["c-break-continue","Changing Loop Flow","Use break to exit a loop and continue to skip to its next iteration.","break exits the nearest loop or switch. continue skips the remainder of the current loop body and proceeds to the next iteration; use both sparingly so flow remains readable.","if (found) { break; }","if (value < 0) { continue; }","for (int i=0; i<10; ++i) { if (i==5) break; }","What does continue do in a loop?","Skips the rest of this iteration","Exits every function","Restarts the whole program","continue advances control to the next iteration."],
    ["c-arrays","Fixed-size Arrays","Store same-typed elements in contiguous positions.","An array has a fixed number of elements and valid indexes from zero to length minus one. C does not perform automatic bounds checks; carry the element count with the array or pass it to functions.","int scores[] = {82, 91, 77};","size_t count = sizeof scores / sizeof scores[0];","for (size_t i=0; i<count; ++i) printf(\"%d\\n\", scores[i]);","What is the last valid index in an array of length n?","n - 1","n","n + 1","Indexes start at zero, so the last index is one below the length."],
    ["c-strings","Null-terminated Character Strings","Represent text with char arrays that end with a null character.","A C string is a sequence of char values terminated by '\\0'. Reserve space for the terminator, check destination capacity, and use bounded operations or safer interfaces rather than overflowing arrays.","char word[] = \"cat\";","size_t length = strlen(word);","printf(\"%s\\n\", word);","What marks the end of a C string?","The null character \\0","A newline in every case","A pointer set to one","String functions rely on the terminating null character."],
    ["c-user-input","Reading User Input Safely","Check input operations and bound the amount of data read.","scanf returns the number of successful conversions, and unbounded %s can overflow a destination. For robust line input, use fgets and parse with functions such as strtol while checking errors and range.","int age; if (scanf(\"%d\", &age) != 1) { return 1; }","char line[128]; if (fgets(line, sizeof line, stdin) == NULL) { return 1; }","char name[40]; scanf(\"%39s\", name);","What should you check after scanf?","Its return value","The terminal color","The CPU temperature","The return value reports how many conversions succeeded."],
    ["c-memory-address","Inspecting Memory Addresses","Use the address-of operator and correct pointer format specifiers.","The & operator obtains an object's address. Store it in a compatible pointer type and use %p with a void pointer conversion when printing an address; addresses may vary between program runs.","int value = 7; int *ptr = &value;","printf(\"%p\\n\", (void *)&value);","size_t bytes = sizeof value;","Which operator obtains an object's address?","&","*","%","The address-of operator produces an object's address."],
    ["c-pointers","Using Pointers","Store and dereference addresses only while their objects are valid.","A pointer can refer to an object or be null. Initialize pointers, check them before dereferencing when null is possible, and never return the address of a local automatic variable.","int value = 7; int *ptr = &value;","if (ptr != NULL) { printf(\"%d\\n\", *ptr); }","int *missing = NULL;","What does *ptr do for a valid pointer?","Accesses the pointed-to object","Returns the pointer's variable name","Allocates memory automatically","Dereferencing accesses the object at the stored address."],
    ["c-function-basics","Defining and Calling Functions","Break a program into named operations with declared types.","A function definition specifies a return type, name, parameters, and body. Keep functions focused and return results explicitly; use void in a parameter list to state that a function accepts no arguments.","int square(int n) { return n * n; }","void greet(void) { puts(\"Hi\"); }","int result = square(5);","What does a function return type describe?","The kind of value produced","The number of source files","The compiler brand","The return type specifies the function's result type."],
    ["c-function-parameters","Passing Function Parameters","Receive values through parameters and avoid unintended side effects.","C passes arguments by value: the function receives a copy. A pointer parameter lets a function modify a caller's object when that is intended, and the contract should make that effect clear.","int add(int a, int b) { return a + b; }","void reset(int *value) { if (value) *value = 0; }","double average(const int values[], size_t count);","How are ordinary C arguments passed?","By value","By reference automatically","As global variables","The function receives copies of ordinary argument values."],
    ["c-pass-by-reference","Changing Caller Data through Pointers","Pass an address when a function must update a caller-owned object.","C has no reference parameter syntax; passing a pointer provides indirect access. Check the pointer contract and do not retain an address beyond the object's lifetime.","void increment(int *n) { if (n) ++(*n); }","int value = 4; increment(&value);","void swap(int *a, int *b) { int t=*a; *a=*b; *b=t; }","How can a C function update a caller's integer?","Receive its pointer","Use a return type of void only","Declare another local variable","A pointer allows the function to modify the original object."],
  ]),
];

cLessons.push(...cChapter("Functions and Program Organization", [
  ["c-scope","Understanding Scope and Lifetime","Know where names are visible and how long objects exist.","Block scope begins at a declaration and ends at the closing brace. Local automatic objects cease to exist when their block ends; never use pointers to expired local objects.","int main(void) { int local = 1; }","static int calls;","void use(void) { { int inner = 2; } /* inner ends here */ }","What happens to an automatic local after its block ends?","Its lifetime ends","It becomes a global","It is automatically freed from the heap","Automatic objects live only within their lifetime."],
  ["c-function-declarations","Declaring Functions Before Use","Provide a prototype so calls are checked before the definition.","A function declaration, or prototype, tells the compiler the return type and parameter types. Place shared declarations in headers with include guards and put one definition in a source file.","int add(int left, int right);","#ifndef MATH_UTIL_H\n#define MATH_UTIL_H\nint square(int n);\n#endif","int add(int left, int right) { return left + right; }","What does a function prototype provide?","The function signature before its definition","The function's runtime output","A memory allocation","A prototype enables compile-time checking of calls."],
  ["c-function-challenges","Function Practice Challenge","Practice decomposing a task into small typed functions.","Write helpers with one responsibility, define their inputs and outputs, and test boundary values. Use a return value for results and pointer parameters only when a caller's object must change.","int clamp(int n, int low, int high);","bool is_even(int n);","void print_menu(void);","What makes a helper function easier to reuse?","A focused purpose and clear interface","Hidden global state","A very long parameter list","A clear contract helps callers use a function correctly."],
  ["c-math-functions","Using the C Math Library","Use math.h functions and link the math library where required.","The math library includes functions such as sqrt, pow, and fabs. Check domain and range requirements, and on some toolchains link with -lm after source files.","double root = sqrt(25.0);","double area = M_PI * radius * radius;","double magnitude = fabs(-2.5);","Which header declares sqrt?","math.h","stdio.h","errno.h","math.h declares common mathematical functions."],
  ["c-inline-functions","Understanding inline Functions","Use inline as a hint and keep correctness independent of optimization.","inline suggests that a function may be expanded at a call site, but the compiler decides whether to do so. It affects linkage rules in C; use a simple static inline helper in a header when appropriate.","static inline int twice(int x) { return x * 2; }","int result = twice(4);","static inline bool positive(int x) { return x > 0; }","Does inline force the compiler to expand a function?","No, it is a request or hint","Yes, in every compiler","Only when the function returns int","Optimization decisions remain with the compiler."],
  ["c-recursion","Solving Problems with Recursion","Use a base case and a smaller recursive step.","A recursive function calls itself on a smaller problem. Every valid path must reach a base case; deep recursion can exhaust the call stack, so iteration may be safer for large inputs.","unsigned factorial(unsigned n) { return n < 2 ? 1 : n * factorial(n - 1); }","int sum_to(int n) { return n <= 0 ? 0 : n + sum_to(n - 1); }","// Base case: an empty range returns zero","What prevents endless recursion?","A base case that stops recursive calls","A global variable","A printf statement","The base case terminates the recursive process."],
  ["c-function-pointers","Calling Functions through Pointers","Store a compatible function address to select behavior dynamically.","A function pointer's type must match the function signature. It is useful for callbacks and dispatch tables; initialize it before calling and compare against null if it can be absent.","int add(int a, int b) { return a+b; }","int (*operation)(int,int) = add;","int result = operation(2, 3);","What must match for a function pointer call?","The function pointer and function signatures","The source file name","The variable's display label","Calling through an incompatible function pointer is not valid."],
  ["c-command-line-args","Reading Command-line Arguments","Accept options and values passed when a program starts.","main can receive argc and argv. argc counts argument strings and argv contains null-terminated strings; validate count and parse numeric values with error checking.","int main(int argc, char *argv[]) { return argc < 2; }","if (argc > 1) { puts(argv[1]); }","// argv[argc] is a null pointer","What does argc count?","The command-line argument strings including the program name","Only flags after --","The number of source files","argc reports the number of entries in argv."],
  ["c-storage-classes","Understanding Storage Duration and Linkage","Control object lifetime and visibility across source files.","Automatic, static, and allocated storage have different lifetimes. The static keyword also affects linkage for file-scope names; distinguish duration from visibility when organizing modules.","static int cached_value;","extern int shared_count;","int local_count;","What does a function-local static object do?","Retains its value between calls","Exists only during one expression","Is allocated by malloc","Static storage duration lasts for the program execution."],
  ["c-organize-code","Organizing C into Headers and Source Files","Separate declarations from implementations in multi-file programs.","Headers expose interfaces and source files provide definitions. Use include guards or #pragma once where supported, avoid defining ordinary global objects in headers, and compile each source file into the final program.","#include \"inventory.h\"","gcc main.c inventory.c -o inventory","/* inventory.h contains declarations */","What belongs in a header?","Declarations shared across source files","Every function body in the project","Only the executable","Headers communicate module interfaces."],
  ["c-macros","Using Preprocessor Macros","Understand textual substitutions and conditional compilation.","The preprocessor handles directives before compilation. Macros can cause surprising substitutions; parenthesize parameters and expansions, and prefer typed functions or constants when they are clearer.","#define MAX_ITEMS 32","#define SQUARE(x) ((x) * (x))","#if defined(DEBUG)\nputs(\"debug\");\n#endif","When does the C preprocessor process #define?","Before the compiler parses the source","After the program exits","During every function call","Preprocessing transforms source before compilation."],
  ["c-bitwise-operators","Bitwise Operations","Manipulate individual bits in integer values.","Bitwise operators work on integer representations. Use unsigned types for bit masks and shifts; avoid shifting by a negative count or by a count at least the width of the type.","unsigned flags = 0u; flags |= 1u << 2;","bool enabled = (flags & (1u << 2)) != 0;","flags &= ~(1u << 2);","What does bitwise AND with a mask help test?","Whether selected bits are set","Whether two strings match","The size of a file","A mask selects bits from an integer value."],
  ["c-fixed-width-integers","Using Fixed-width Integer Types","Choose exact-width integer types when a protocol or file format requires them.","stdint.h defines types such as uint32_t when the implementation provides an exact width. Use them for binary formats and interfaces with fixed sizes; use size_t for object sizes and array lengths.","uint32_t packet_size = 1024;","int64_t timestamp = 0;","size_t bytes = sizeof(double);","Which type is designed for object sizes?","size_t","char for every size","float","size_t is the standard unsigned type for sizes."],
]));

cLessons.push(...cChapter("Errors, Validation, and Problem Solving", [
  ["c-errors","Recognizing C Program Errors","Separate compiler diagnostics, runtime failures, and logic mistakes.","Compiler diagnostics describe invalid or suspicious source; runtime failures occur during execution; logic errors produce the wrong result. Read the first relevant message and reduce an issue to a small example.","gcc -Wall -Wextra -Wpedantic program.c","./program < sample.txt","printf(\"value=%d\\n\", value);","What is a logic error?","The program runs but computes an unintended result","A compiler executable","A comment typo only","Logic errors concern behavior, not necessarily compilation."],
  ["c-debugging","Debugging with Compiler Tools","Use warnings, debug symbols, breakpoints, and sanitizers.","Reproduce a failure, inspect state, isolate the smallest failing case, and verify the fix. Debug builds can include symbols, and sanitizers can expose certain memory errors during tests.","gcc -g -Wall -Wextra app.c -o app","gdb ./app","gcc -fsanitize=address -g app.c -o app","What does a debugger breakpoint do?","Pauses execution at a chosen location","Deletes a function","Changes a variable type","Breakpoints allow inspection at a point of interest."],
  ["c-null-pointers","Checking for Null Pointers","Represent and detect the absence of an object address.","NULL is a null pointer constant. Check pointers that may be absent before dereferencing; a non-null pointer is not automatically valid if its object has expired or the pointer is corrupted.","int *p = NULL;","if (p != NULL) { use(*p); }","int *p = malloc(sizeof *p); if (p == NULL) return EXIT_FAILURE;","Does non-null guarantee a safe pointer?","No, its object must also be valid and alive","Yes, always","Only if it is global","Pointer validity involves more than just a non-null value."],
  ["c-error-handling","Reporting Errors with Status Codes","Return enough information for a caller to respond to failures.","C APIs often return a status code, use an output parameter, or return a sentinel with a documented meaning. Check results and release acquired resources on error paths.","if (fopen(path, \"r\") == NULL) { perror(path); }","if (parse(input, &value) != 0) { return ERROR_PARSE; }","return EXIT_FAILURE;","Why check a function status result?","It communicates whether the operation succeeded","It creates a global variable","It converts all errors to warnings","Status values let callers choose a safe next step."],
  ["c-input-validation","Validating Numeric Input","Parse text, detect malformed values, and enforce allowed ranges.","strtol exposes an end pointer and range errors. First verify that some digits were parsed and all input was consumed, then check the application's minimum and maximum.","char *end; errno = 0; long n = strtol(text, &end, 10);","if (errno == ERANGE || end == text || *end != '\\0') { reject(); }","if (n < 0 || n > MAX_ITEMS) { reject(); }","What does strtol's end pointer help detect?","Unconsumed characters after the number","A missing header","Whether memory was freed","The end pointer reveals trailing invalid text."],
  ["c-problem-solving","A Method for Solving Problems","Clarify inputs and outputs, then break a task into smaller steps.","Write examples by hand, note constraints, choose a representation, and implement a simple correct solution before optimizing. State assumptions such as whether an input collection can be empty.","// Input: a sequence of scores","// Output: the largest score","// Plan: initialize, scan, update","Why clarify constraints before coding?","They determine valid inputs and useful choices","They remove the need for tests","They guarantee fastest code","Constraints shape algorithms and edge cases."],
  ["c-build-the-logic","Building Algorithm Logic","Use loop invariants to reason about each step.","An invariant is a fact maintained during a loop, such as the current maximum being the largest value seen so far. It helps with initialization and loop boundaries.","int max = values[0];","for (size_t i=1; i<count; ++i) if (values[i]>max) max=values[i];","// Invariant: max is largest among processed values","What does a loop invariant describe?","A property maintained through iterations","A warning level","A file permission","Invariants help justify algorithm steps."],
  ["c-edge-cases","Testing Edge Cases and Errors","Try empty, minimum, maximum, and malformed inputs.","Boundary cases expose hidden assumptions. Check zero length before accessing element zero, guard arithmetic limits, and test failure behavior as well as successful output.","if (count == 0) return EMPTY_INPUT;","if (count > SIZE_MAX / sizeof *items) return SIZE_OVERFLOW;","// test empty, one item, and duplicates","Why test an empty array separately?","There is no valid element at index zero","C fills it with a default","It always causes a compiler error","An empty collection has no valid element index."],
  ["c-test-cases","Writing C Test Cases","Compare function results with expected values.","Test normal, boundary, and failure cases. Keep inputs deterministic and verify both return values and output parameters; sanitizers can help find memory problems.","assert(add(2, 3) == 5);","assert(clamp(-1, 0, 9) == 0);","assert(parse_int(\"bad\", &value) == ERROR_INPUT);","What does assert check?","That an expression is true at that point","That memory frees automatically","That the program is portable","Assertions check expected conditions during development."],
]));

cLessons.push(...cChapter("Files and Input", [
  ["c-create-files","Creating and Opening Files","Use stdio file streams and check whether opening succeeded.","fopen opens a file and returns a FILE pointer or null on failure. File paths and modes matter; close streams with fclose and inspect return values for errors.","FILE *file = fopen(\"notes.txt\", \"w\");","if (file == NULL) { perror(\"fopen\"); return 1; }","fclose(file);","What does fopen return when it cannot open a file?","A null pointer","An empty FILE object","The file's first byte","Failure is reported with a null pointer."],
  ["c-write-files","Writing Text to Files","Write formatted or raw data and check for I/O failures.","fprintf writes formatted text to a stream; fputs writes a string. Check results and fclose because buffered output errors may appear during closing.","fprintf(file, \"Score: %d\\n\", score);","fputs(\"Saved\\n\", file);","if (fclose(file) == EOF) { perror(\"close\"); }","Why check fclose after writing?","Buffered write errors may be reported then","It automatically deletes the file","It converts the file into a pointer","Closing flushes buffered output and can report a failure."],
  ["c-read-files","Reading Data from Files","Read streams while handling end-of-file and input errors.","fgets reads at most a bounded number of characters into a buffer and includes a newline when it fits. Check its return value and distinguish end-of-file from other read errors when needed.","char line[128]; if (fgets(line, sizeof line, file)) { puts(line); }","int ch; while ((ch = fgetc(file)) != EOF) { putchar(ch); }","if (ferror(file)) { perror(\"read\"); }","What does fgets help control?","The maximum number of characters read into a buffer","The number of files in a directory","The compiler version","The buffer size argument bounds the read."],
  ["c-file-challenges","File Handling Practice","Combine file opening, line processing, and cleanup.","A file-processing task should handle missing files, long lines, parse failures, and cleanup on every path. Use a small fixture file so the behavior is repeatable.","FILE *in = fopen(path, \"r\");","while (fgets(line, sizeof line, in)) { ++line_count; }","if (in) fclose(in);","What should a file exercise always consider?","Open, read, and close failures","Only the filename color","The current screen size","Robust file code handles failure at each I/O step."],
]));

cLessons.push(...cChapter("Structures and Enumerations", [
  ["c-structs","Grouping Data with Structures","Combine fields of different types into one record.","A struct defines a record type with named members. Initialize members deliberately and pass large structures by pointer when copying them would be unnecessary.","struct Point { int x; int y; };","struct Point origin = { .x = 0, .y = 0 };","printf(\"%d\\n\", origin.x);","What does a struct group?","Related values, possibly of different types","Only one integer type","Function names only","Structures represent related fields as one object."],
  ["c-struct-challenges","Structure Practice","Model a small record and write functions that use it.","Choose fields that describe one entity, initialize them, and write helpers that accept the structure. Test empty, boundary, and representative values.","struct Student { unsigned id; char name[40]; };","struct Range { int low; int high; };","bool contains(struct Range r, int x);","What is a useful struct design?","A small group of fields describing one concept","A random list of unrelated globals","A replacement for every array","A record is most useful when its fields belong together."],
  ["c-nested-structs","Nesting Structures","Represent a composed value using another struct as a member.","A structure can contain another structure by value. This creates an explicit hierarchy; choose pointer members only when shared identity or dynamic lifetime is needed.","struct Date { int year, month, day; };","struct Event { char title[40]; struct Date starts; };","event.starts.month = 6;","How do you access a nested member?","Use member access at each level","Use SQL JOIN syntax","Dereference every member","Nested structure members use the dot operator repeatedly."],
  ["c-arrays-of-structs","Arrays of Structures","Store multiple records contiguously and process each one.","An array of structures stores fixed-size records. Keep the element count, avoid indexing beyond it, and use qsort only with a comparator that matches the member being ordered.","struct Point points[3] = {{0,0},{1,2},{3,4}};","for (size_t i=0; i<3; ++i) printf(\"%d\\n\", points[i].x);","struct Student class_list[30];","What is each array element?","One complete structure value","A pointer to the whole program","A separate source file","Each array slot contains one structure object."],
  ["c-struct-pointers","Pointers to Structures","Access structure members through a pointer safely.","A pointer to a structure refers to an existing struct object. The arrow operator is shorthand for dereference followed by member access; verify the pointer is valid first.","struct Point p = {1, 2}; struct Point *ptr = &p;","printf(\"%d\\n\", ptr->x);","ptr->y = 9;","What is ptr->x equivalent to?","(*ptr).x","&ptr.x","ptr.x","The arrow operator accesses a member through a structure pointer."],
  ["c-unions","Sharing Storage with Unions","Understand types whose members overlap in memory.","A union allocates storage large enough for its largest member, and its members share that storage. Track which member is currently meaningful; a tagged union pairs it with an enum or other discriminator.","union Number { int i; float f; };","union Number n = {.i = 12};","enum Kind { INTEGER, FLOATING };","How do union members use storage?","They overlap the same memory","Each gets a separate allocation","They are automatically converted","A union provides shared storage for alternative representations."],
  ["c-typedef","Creating Type Aliases with typedef","Give an existing type a convenient name.","typedef introduces an alias rather than a completely new distinct type. Use it when it makes interfaces clearer, while retaining explicit pointer and const details in declarations.","typedef unsigned long UserId;","typedef struct Point Point;","Point *point = NULL;","Does typedef create a distinct runtime type?","No, it creates an alias","Yes, it allocates an object","It creates a function","typedef changes the name used to refer to a type."],
  ["c-struct-padding","Structure Layout and Padding","Understand that member layout may include implementation-defined padding.","Compilers may insert padding to meet alignment requirements, so sizeof a structure may exceed the sum of its members. Do not serialize raw struct bytes as a portable file format without defining layout and byte order.","printf(\"%zu\\n\", sizeof(struct Record));","offsetof(struct Record, value);","_Alignof(struct Record);","Why can sizeof a struct include extra bytes?","Alignment padding may be inserted","Every field is stored twice","The compiler appends the source file","Padding aligns members for efficient and valid access."],
  ["c-enums","Naming States with Enumerations","Give related integer constants readable names.","An enum defines named integer constants and can make state transitions clearer. Validate values read from external input; an enum variable can still hold values outside the named set.","enum Status { STATUS_NEW, STATUS_DONE };","enum Status state = STATUS_NEW;","if (state == STATUS_DONE) { finish(); }","Are enum values automatically restricted to listed names?","No, validate values from outside the program","Yes, hardware enforces the list","Only when declared const","C enum objects can contain other integer values."],
]));

cLessons.push(...cChapter("Memory Management and Safety", [
  ["c-memory-management","Understanding Dynamic Memory","Choose stack or allocated storage and define ownership clearly.","Automatic objects have block lifetime; allocated objects remain until released. Every allocation needs a clear owner and cleanup path, and object sizes should be computed from the pointed-to type.","int local = 3;","int *values = malloc(count * sizeof *values);","free(values);","What must happen to a successful allocation?","It must eventually be released by its owner","It is freed automatically at the end of every statement","It must be returned by main","Allocated storage remains until explicitly released."],
  ["c-allocate-memory","Allocating Memory with malloc and calloc","Request storage and check both the size calculation and result.","malloc returns uninitialized storage; calloc zero-initializes allocated bytes. Check allocation failure and guard against multiplication overflow when calculating an array size from untrusted counts.","int *p = malloc(count * sizeof *p);","int *zeroed = calloc(count, sizeof *zeroed);","if (p == NULL) { return EXIT_FAILURE; }","What does malloc initialize the bytes to?","No defined initial value","Always zero","The ASCII character '0'","malloc returns uninitialized storage."],
  ["c-access-memory","Accessing Allocated Memory","Stay within allocated bounds and use objects only during their lifetime.","Before reading or writing through a pointer, ensure it refers to a live object and that the index is in range. One-past-the-end pointers may be formed but not dereferenced.","values[0] = 10;","for (size_t i=0; i<count; ++i) use(values[i]);","int *end = values + count;","May a one-past-the-end pointer be dereferenced?","No","Yes, if it is not null","Only when allocated by calloc","The one-past pointer can mark an endpoint but is not an element."],
  ["c-reallocate-memory","Resizing Memory with realloc","Change an allocation size without losing the original pointer on failure.","realloc may move the allocation, and if it fails the original block remains allocated. Store the result in a temporary pointer; avoid using old interior pointers after a successful move.","void *tmp = realloc(data, new_count * sizeof *data);","if (tmp != NULL) { data = tmp; }","if (tmp == NULL) { /* keep data and handle failure */ }","Why use a temporary pointer with realloc?","Failure leaves the original allocation valid","realloc always frees on failure","The old pointer never changes","A temporary preserves access to the old block if resizing fails."],
  ["c-deallocate-memory","Releasing Memory with free","Release each owned allocation exactly once.","free accepts null or a pointer returned by a compatible allocation function. After freeing, do not access the object or free the same allocation again; set owner pointers to null when useful.","free(buffer);","buffer = NULL;","free(NULL);","What can happen after an allocation is freed?","Using the old pointer is invalid","The memory becomes a valid string","The compiler recreates its contents","A freed object's lifetime has ended."],
  ["c-structs-and-memory","Allocating Structures and Their Members","Manage ownership for an object and any separately allocated fields.","Allocating a struct does not automatically allocate memory for pointer members. Initialize and release each owned member, and write cleanup functions that handle partial initialization.","struct User *u = malloc(sizeof *u);","u->name = malloc(name_len + 1);","free(u->name); free(u);","Does allocating a structure allocate memory for a pointer member's target?","No, that target needs its own allocation","Yes, always","Only if the member is first","Pointer fields store addresses, not automatic storage for their targets."],
  ["c-memory-example","Building a Small Dynamic Array","Combine allocation, bounds, and cleanup in one example.","A dynamic array tracks both pointer and length or capacity. Check arithmetic and allocations, keep the owner responsible for free, and avoid returning a pointer to local storage.","size_t count = 3; int *scores = malloc(count * sizeof *scores);","if (scores) { scores[0]=70; scores[1]=85; scores[2]=92; }","free(scores);","What should accompany a dynamic array pointer?","Its length or capacity","A copy of the compiler","A global variable name","The program needs a bound to safely access its elements."],
  ["c-memory-mistakes","Avoiding Common Memory Bugs","Recognize leaks, dangling pointers, double frees, and out-of-bounds access.","Common errors include losing an allocation, reading freed storage, freeing twice, and indexing past an array. Use ownership conventions, compiler warnings, sanitizers, and small focused tests to find them.","gcc -fsanitize=address -g program.c -o program","// free exactly once for each owned allocation","// check index < length before access","What is a memory leak?","Allocated memory becomes unreachable without being freed","An array has a name","A function returns zero","Lost ownership can keep allocated storage unavailable for reuse."],
]));

cLessons.push(...cChapter("Data Structures and Practice", [
  ["c-dsa-intro","Data Structures and Algorithms","Choose a representation and algorithm for the task.","A data structure organizes values; an algorithm describes operations on them. In C, representation includes ownership, size, and lifetime as well as speed.","size_t length = 0;","struct Node { int value; struct Node *next; };","// choose an array for indexed access","What should guide a data-structure choice?","Required operations, constraints, and ownership","The shortest type name","A random header","A representation should fit the problem and its operations."],
  ["c-searching","Searching a Collection","Find an item with linear or binary search.","Linear search works on any sequence and takes time proportional to length. Binary search is faster for sorted data but requires sorted input and careful interval boundaries.","for (size_t i=0; i<n; ++i) if (a[i] == key) return i;","bsearch(&key, values, count, sizeof values[0], compare_int);","// binary search requires sorted values","When is binary search appropriate?","When data is sorted and comparisons are ordered","For every unsorted list","Only for strings with spaces","Binary search relies on sorted order to discard half the range."],
  ["c-sorting","Sorting Values","Order an array using a clear comparison rule.","Sorting can use simple algorithms for learning or library qsort for general use. A comparator must return negative, zero, or positive without overflowing arithmetic.","qsort(values, count, sizeof values[0], compare_int);","int compare(const void *a,const void *b){ int x=*(const int*)a,y=*(const int*)b; return (x>y)-(x<y); }","// test empty, sorted, and reversed arrays","Why avoid returning x - y in a comparator?","Subtraction can overflow","It returns a string","It reverses pointers","Relational comparisons avoid overflow while expressing order."],
  ["c-stacks","Building a Stack","Use last-in, first-out operations for nested or recent work.","A stack pushes and pops at one end. Track capacity for an array implementation and check underflow before popping; a linked implementation needs clear allocation ownership.","stack_push(&s, value);","if (!stack_empty(&s)) value = stack_pop(&s);","// push A, push B, pop returns B","Which item comes out first from a stack?","The most recently pushed item","The oldest item","A random item","Stacks use last-in, first-out order."],
  ["c-queues","Building a Queue","Process items in first-in, first-out order.","A queue adds at the back and removes from the front. A circular array can reuse space; check full and empty states before enqueue and dequeue.","queue_enqueue(&q, task);","task = queue_dequeue(&q);","// enqueue A, enqueue B, dequeue returns A","Which item comes out first from a queue?","The earliest item waiting","The latest item","The item with largest address","Queues use first-in, first-out order."],
  ["c-linked-lists","Building a Linked List","Connect nodes through pointers for flexible insertion and traversal.","A singly linked list stores a value and next pointer per node. Traversal follows links until null; free each allocated node and handle the empty-list case.","struct Node { int value; struct Node *next; };","for (struct Node *p=head; p; p=p->next) visit(p->value);","// after removing a node, free it once","What marks the end of a singly linked list?","A null next pointer","A zero data item","The last array index","A null link indicates there is no next node."],
  ["c-trees","Representing Trees","Model hierarchical relationships with linked nodes.","A tree node may point to child nodes, and a binary tree has at most two children. Define ownership and traversal order; guard recursive algorithms against deep trees.","struct Tree { int value; struct Tree *left, *right; };","// preorder: node, left, right","// inorder: left, node, right","What is a binary node allowed to have?","At most two child links","Exactly two parents","No data value","Binary nodes have up to two children."],
  ["c-hash-tables","Using a Hash Table","Map keys to buckets for efficient average-case lookup.","A hash table maps a key to a bucket using a hash function. Collisions must be handled, keys need consistent equality rules, and performance depends on load and hash quality.","size_t bucket = hash(key) % capacity;","// compare full keys after a collision","// resize as load factor grows","What is a hash collision?","Different keys map to the same bucket","A compiler error","A null check","Hashing can send multiple keys to one bucket."],
  ["c-big-o","Reasoning About Big O","Describe how algorithm work grows as input size increases.","Big O describes a growth pattern rather than exact runtime. Linear search is O(n), binary search on sorted data is O(log n), and nested full scans may be O(n squared).","// linear scan: O(n)","// binary search: O(log n)","// nested pair scan: O(n^2)","What does Big O summarize?","How resource use grows with input size","Exact milliseconds","The number of source files","Big O describes growth as the input scales."],
  ["c-projects","Planning a C Project","Combine modules, input handling, and tests in a small application.","Start with a clear goal such as a score tracker or text analyzer. Define inputs, data structures, modules, error paths, and tests before adding optional features.","// src/main.c","// include/project.h","gcc -std=c11 -Wall -Wextra src/main.c src/data.c -o app","What should a project plan identify early?","Inputs, outputs, data model, and failure cases","Only a logo","The final binary size","Planning keeps implementation focused."],
  ["c-real-life-examples","Applying C to Systems Problems","Relate language features to embedded and systems tasks.","C is used in constrained and systems environments where memory, timing, and interfaces matter. Prefer explicit bounds and testable modules, and use platform APIs only when the target is known.","uint8_t packet[64];","size_t used = 0;","if (used < sizeof packet) packet[used++] = byte;","Why are explicit bounds useful?","They prevent writes outside available storage","They remove types","They make code platform-independent","Bounds clarify how much memory is available."],
  ["c-exercises","C Exercises and Practice Problems","Strengthen core skills with small programs and repeated testing.","Practice expressions, arrays, functions, string parsing, and structures in increasing combinations. Compile with warnings and test empty, boundary, and invalid inputs.","// find the largest array value","// count words in a bounded line","// store records in a struct array","What makes a useful practice progression?","Combine concepts gradually and test each step","Start with unsafe memory tricks","Skip compiler diagnostics","Layered exercises build on earlier concepts."],
  ["c-code-challenges","C Code Challenges","Solve constrained tasks while keeping memory and bounds safe.","For each challenge, write the contract, choose an algorithm, handle invalid input, and test edge cases. Optimize only after measuring a correct version.","// reverse a string within its known length","// merge two sorted arrays","// parse integers and report invalid tokens","What should be checked before optimizing?","Correctness on representative and boundary inputs","Only comment count","Whether names are short","Test correctness before optimizing."],
  ["c-certificate-preparation","C Skills Review","Review language, memory, and problem-solving skills.","A strong review includes types, control flow, functions, arrays, strings, pointers, allocation, files, and debugging. Build a small project and explain ownership and bounds choices.","gcc -std=c11 -Wall -Wextra -Wpedantic app.c -o app","./app < sample.txt","// review allocations, bounds, and error paths","What should a C study plan include?","Hands-on coding plus memory and error handling","Only syntax names","Only memorized output","C skills include safe resource management."],
  ["c-interview-questions","C Interview Review","Explain common trade-offs with examples and precise terms.","Practice explaining pointers, array decay, storage duration, undefined behavior, struct padding, and ownership. State assumptions instead of guessing when behavior is implementation-dependent.","sizeof array / sizeof array[0]","const int *p;","// explain why signed overflow is undefined","What makes an interview explanation strong?","Precise reasoning with assumptions and an example","A guessed one-word answer","An unrelated feature","Clear reasoning demonstrates understanding."],
  ["c-syllabus-study-plan","C Syllabus and Study Sequence","Progress from syntax through memory and data structures.","Begin with compilation and types, then control flow, functions, arrays, strings, and pointers. Continue to files, structs, dynamic memory, debugging, and algorithms while practicing each stage.","// Stage 1: expressions and branches","// Stage 2: functions, arrays, strings","// Stage 3: pointers, allocation, data structures","Why study pointers after arrays and functions?","They build on addresses and parameter passing","They are unrelated to memory","They replace testing","Earlier concepts make pointer behavior easier to reason about."],
]));

cLessons.push(...cChapter("C Library Reference", [
  ["c-reference-overview","C Standard Library Overview","Recognize common headers and the facilities they declare.","The C standard library provides I/O, memory, strings, math, character checks, time, and diagnostics. Include the correct header and check each function's return contract.","#include <stdio.h>","#include <stdlib.h>","#include <string.h>","Why include a library header?","It declares interfaces needed by the program","It installs the compiler","It allocates every global variable","Headers provide declarations and macros for a library interface."],
  ["c-keywords-reference","C Keywords and Language Terms","Recognize reserved words and core language constructs.","Keywords such as int, return, if, while, struct, and sizeof have fixed language meaning. They cannot be used as ordinary identifiers; compiler versions may add keywords in newer standards.","int count;","if (count > 0) return count;","sizeof count","Can a C keyword be used as an ordinary variable name?","No","Yes, in every C standard","Only in headers","Keywords are reserved for the language grammar."],
  ["c-preprocessor-reference","Preprocessor Directives","Use include, define, and conditional compilation deliberately.","Preprocessor directives begin with # and are handled before compilation. Include guards prevent repeated header contents, while conditional compilation can select platform-specific code.","#include <stdint.h>","#define LIMIT 20","#ifdef DEBUG\nputs(\"trace\");\n#endif","When are directives processed?","Before normal compilation","After the program exits","During each function call","The preprocessor transforms source before compilation."],
  ["c-assert-reference","Checking Invariants with assert.h","Use assertions for conditions that should hold during development.","assert checks an expression and reports a failure in debug builds. Do not use it to validate ordinary user input or to perform side effects, because NDEBUG can disable assertions.","#include <assert.h>","assert(count <= capacity);","assert(ptr != NULL);","Should assert be the only way to validate user input?","No, handle input errors explicitly","Yes, assertions always run in production","Only for strings","Assertions are for programmer assumptions, not recoverable input checks."],
  ["c-ctype-reference","Classifying Characters with ctype.h","Test character classes safely with standard functions.","Functions such as isdigit and isspace accept EOF or values representable as unsigned char. Cast a possibly signed char before passing it to these functions.","isdigit((unsigned char)ch);","isspace((unsigned char)ch);","tolower((unsigned char)ch);","Why cast char to unsigned char for ctype functions?","Other negative char values are outside the valid argument range","It converts the character to UTF-8","It avoids including a header","ctype functions require EOF or an unsigned-char value."],
  ["c-errno-reference","Checking errno","Inspect errno when a library function documents it as an error indicator.","errno is meaningful only when a function's contract says it sets it, and success does not always reset it. Set it to zero before conversions where needed and inspect the function's return value first.","errno = 0;","long value = strtol(text, &end, 10);","if (errno == ERANGE) { /* handle range */ }","Should errno alone determine whether a call succeeded?","No, check the function's documented return value too","Yes, it is reset automatically every time","Only for printf","The return contract is primary; errno adds detail for certain failures."],
  ["c-limits-reference","Using limits.h","Read implementation limits for fundamental integer types.","limits.h defines values such as INT_MAX and CHAR_BIT for the current implementation. Use these limits instead of assuming a type width or range.","if (value == INT_MAX) { /* avoid increment overflow */ }","printf(\"%d\\n\", CHAR_BIT);","long max_value = LONG_MAX;","What does INT_MAX describe?","The largest int value for this implementation","The maximum array length in every program","The compiler's optimization level","limits.h exposes implementation-specific type limits."],
  ["c-math-reference","Using math.h","Use common math operations with floating-point values.","math.h declares functions such as sqrt, ceil, floor, and fabs. Check domain restrictions and precision requirements; link the math library if your platform's toolchain requires it.","sqrt(81.0);","ceil(2.2);","floor(2.8);","Which header declares sqrt?","math.h","string.h","errno.h","math.h declares common math operations."],
  ["c-boolean-reference","Using stdbool.h","Use bool, true, and false names in C99 and later.","stdbool.h provides readable boolean spellings in modern C standards. Conditions still follow C truth rules, and integer values may be converted to bool.","bool ready = true;","bool valid = (count > 0);","if (!valid) { return 1; }","What does bool represent?","A true-or-false value","A file handle","A dynamic array","bool provides a readable type for logical state."],
  ["c-size-and-integer-reference","Using stddef.h and stdint.h","Use size and fixed-width integer types where their contracts fit.","stddef.h defines size_t and NULL; stdint.h provides optional exact-width integer types. Use size_t for sizes and indexes, and fixed-width types for binary interfaces that require them.","size_t length = sizeof values;","uint32_t flags = 0;","ptrdiff_t distance = end - begin;","Which type is intended for sizes?","size_t","float","void","size_t represents object sizes and counts."],
  ["c-stdio-reference","Using stdio.h","Work with standard streams and formatted input/output.","stdio.h declares printf, fgets, FILE, and related functions. Check return values for I/O, bound input buffers, and avoid unsafe unbounded string reads.","printf(\"Ready\\n\");","fgets(line, sizeof line, stdin);","FILE *file = fopen(path, \"r\");","Which function reads a bounded line into a buffer?","fgets","gets","puts","fgets takes the destination buffer size."],
  ["c-stdlib-reference","Using stdlib.h","Access allocation, conversion, sorting, and process utilities.","stdlib.h declares functions such as malloc, free, strtol, qsort, and exit. Check results and prefer conversions with error reporting over simple functions that cannot distinguish invalid input.","void *p = malloc(bytes);","long n = strtol(text, &end, 10);","qsort(items, count, sizeof items[0], compare);","Which function releases an allocation?","free","fclose","remove","free releases storage obtained from allocation functions."],
  ["c-string-reference","Using string.h","Measure, compare, and copy strings while respecting buffer capacity.","string.h declares functions like strlen, strcmp, and memcpy. Many functions do not know the destination buffer capacity; validate lengths and leave room for a terminating null byte when making C strings.","size_t n = strlen(text);","int order = strcmp(left, right);","memcpy(destination, source, bytes);","What does strcmp return?","A value indicating lexical comparison","The string length always","A pointer to the longer string","strcmp compares strings and indicates their ordering."],
  ["c-time-reference","Using time.h","Read clock values and format calendar time with care.","time.h provides time-related types and functions. Local time and UTC differ; check conversion results and avoid assuming a time_t representation has one portable width or encoding.","time_t now = time(NULL);","struct tm *utc = gmtime(&now);","strftime(buffer, sizeof buffer, \"%Y-%m-%d\", utc);","Should code assume time_t has a fixed width everywhere?","No, its representation is implementation-dependent","Yes, it is always 32-bit","It is always text","Portable code treats time_t as an implementation-defined time representation."],
  ]));
